from pathlib import Path
import json,re
r=Path('src/main/resources');p=r/'data/kelmagic/research/catalog.json';j=json.loads(p.read_text())
examples={
'archivist_table':'Я могу поставить стол там, где удобно сравнивать образцы, и положить рядом лист с вопросом. Малый образец поможет удержать мысль; дорогие вещи лучше пока оставить в сундуке.\n\nМонокль приближает строки открытой книги, пока я смотрю на страницу. Его можно держать в руке или закрепить на шлеме. Когда взгляд уходит от книги, мир снова становится привычным.',
'monocle':'Монокль приближает строки открытой книги на столе. Его можно держать в руке или закрепить на шлеме; тогда руки останутся свободными. Когда взгляд уходит со страницы, мир снова становится привычным.',
'archivist_cabinet':'Шкафы собираются из сумеречных досок. Соседние секции, соприкасающиеся стенками, полом или крышей, открываются как общее хранилище. На фасаде видны оставленные вещи. Если снять секцию, наружу попадёт лишь то, что хранилось в ней.\n\nШкаф рукописей бережёт книги, бумагу и записи отдельно от прочих вещей. Оба ремесла выросли из одной мысли.',
'manuscript_cabinet':'Соседние секции соединяются в общее хранилище рукописей. Книги и листы видны на фасаде. Сюда не ложатся чуждые письму вещи; снятая секция отдаёт только свои записи.',
'archivist_ink':'Чернила оживляют надпись на обращённой ко мне стороне таблички, если её не защитил воск. В воздухе можно выбрать знак: букву, стрелку, лицо или маленький рисунок. Присев у полной плоской грани, я переношу его на поверхность. Ластик стирает мой почерк. Чужая запись остаётся за её автором.',
'magic_sapling':'Похоже, магические леса вымерли на этой земле. Саженцы, полученные магическим наполнением, — лишь бесплодные ростки: они ещё способны стать деревьями, но не дают потомства.\n\nЯ высажу росток на открытой земле, оставив простор для тяжёлых корней и широкой кроны. Костная мука помогает ему проснуться. Иногда среди сумеречных листьев мерцают золотистые; под ними можно найти золотой плод. Ножницы сохраняют саму листву.',
'midnight_wood':'Корни выступают из земли, будто пальцы, удерживающие память исчезнувшего леса. Тёмная древесина принимает обычные столярные формы: доски, ступени, двери, люки и прочую утварь. Из неё я могу собрать пьедестал и шкафы.\n\nСумеречное основание, золотое полотно и узел маны складываются в кровать потусторонних снов. Она принимает спящего даже там, где обычная постель опасна, и помогает душе запомнить путь обратно. Место рядом должно оставаться свободным.\n\nЖивое волокно, вплетённое в обычный дёрн, пробуждает магическую траву. Тихая волна проходит по её ковру: синий сумрак медленно уступает яркому фиолетовому и возвращается вновь.',
'living_fiber':'Сумеречные доски можно расщепить на гибкое живое волокно. Оно служит деревянным связующим в ремесле, а в обычном дёрне пробуждает память о магической траве.',
'resonance_glass':'Когда прозрачные грани соприкасаются, их внутренние швы исчезают. Общий узор остаётся по краю окна, словно огранка единого кристалла. Я могу собирать большие прозрачные поверхности, не закрывая мир за ними.'}
for n in j['nodes']:
 if n['id'] in examples:n['example']=examples[n['id']]
 for k in ['thought','example']:
  assert not re.search(r'[0-9%]|\bnov\b|Curios|NBT|тег |клиент|сервер|незагруженн',n.get(k,'')),(n['id'],k)
p.write_text(json.dumps(j,ensure_ascii=False,indent=2)+'\n')
for lang in ['ru_ru','en_us']:
 p=r/f'assets/kelmagic/lang/{lang}.json';j=json.loads(p.read_text())
 j['lore.kelmagic.archivist_cabinet']=('Шкафы помнят, где лежит каждая вещь. Соседние секции открываются вместе, но не теряют собственной памяти.\n\nШкаф рукописей бережёт книги и листы отдельно от прочих предметов.' if lang=='ru_ru' else 'Joined cabinets share a door without forgetting where each object belongs. Manuscript cabinets keep books and papers apart from other belongings.')
 j['lore.kelmagic.magic_sapling']=('Похоже, магические леса вымерли на этой земле. Саженцы, полученные магическим наполнением, — лишь бесплодные ростки: они могут стать деревьями, но потомства уже не оставят.' if lang=='ru_ru' else 'The magical forests seem to have died out in this land. Saplings born of magical infusion are only barren shoots: they can still become trees, but bear no descendants.')
 p.write_text(json.dumps(j,ensure_ascii=False,indent=2)+'\n')
